const games = [{"name": "Original Diablo II", "edition": "LoD-era guide \u2022 NOT D2R", "ids": ["D2-06", "D2-01", "D2-03"], "summary": "Compact HUD gameplay. Dark floor leaves luminous shards legible, but overlapping bodies still hide anatomy. Tall walls and sarcophagi interrupt floor visibility.", "images": [{"id": "D2-06", "data": "data:image/jpeg;base64,", "observation": "Isolated caster in cave with torches, stalagmites, shadow and open floor. Quiet instant only, not a traversal segment.", "url": "https://classic.battle.net/images/battle/diablo2exp/images/skills/frozenarmor02.jpg"}, {"id": "D2-01", "data": "data:image/jpeg;base64,", "observation": "HUD-equipped Frozen Orb dungeon: bright detached shards cross dark ground; central bodies overlap; foreground tomb/rock hides floor. Body isolation indeterminate.", "url": "https://classic.battle.net/images/battle/diablo2exp/images/skills/frozenorb01.jpg"}, {"id": "D2-03", "data": "data:image/jpeg;base64,", "observation": "Hire-mercenary dialog over camp grass and wagon. Establishes visible NPC interaction UI, not navigation or normal camera framing.", "url": "https://classic.battle.net/images/battle/diablo2exp/images/npcs/hire01.jpg"}]}, {"name": "Path of Exile 1", "edition": "Steam app 238960 \u2022 NOT PoE2", "ids": [null, "POE-04", "POE-02"], "summary": "HUD-equipped combat and large prop silhouettes. Ground detail survives in gaps between thin effects; bright gear and effects prevent reliable tight-body measurement. Quiet traversal and hideout coverage are missing.", "images": [null, {"id": "POE-04", "data": "data:image/jpeg;base64,", "observation": "PoE1 HUD; central actor to right of tall wooden fence, large monster at left, ground ring and fire/blue effects. Equipment obscures true head boundary; body height uncertain.", "url": "https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/238960/ss_26a455ad97d62bc249ea4c05ce0a0a9459874509.1920x1080.jpg?t=1784681738"}, {"id": "POE-02", "data": "data:image/jpeg;base64,", "observation": "PoE1 HUD; barrels, tall industrial wall and machine amid melee. Blue line-like arcs retain gaps through which ground is visible; red effects overlap central body.", "url": "https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/238960/ss_7c3a8d17ef017d38bdf87cf61eb0c8a632e741d6.1920x1080.jpg?t=1784681738"}]}, {"name": "Grim Dawn", "edition": "Base / AoM / FG rows kept separate", "ids": ["GD-05", "GD-03", "GD-04"], "summary": "The repaired/broken bridge pair is concrete art/state evidence. Actor framing varies markedly across promotional captures; one screenshot cannot set a game-wide scale.", "images": [{"id": "GD-05", "data": "data:image/jpeg;base64,", "observation": "Same viewpoint and actor vicinity as GD-04; bridge visibly spans gap; dialog removed. Supports before/after visible geometry only, not transition correctness.", "url": "https://www.grimdawn.com/wp-content/uploads/sites/3/2019/09/game_bridgeFixed01.jpg"}, {"id": "GD-03", "data": "data:image/jpeg;base64,", "observation": "HUD scene: isolated armored player beside huge beast on pale sand; gold ground effect, contact shadows and exposed rock tops visible. Zoom setting unknown.", "url": "https://www.grimdawn.com/wp-content/uploads/sites/3/2019/06/2019-03-GDX2_08.png"}, {"id": "GD-04", "data": "data:image/jpeg;base64,", "observation": "Devil\u2019s Crossing: broken bridge behind tall gate arch; repair dialog visible. Guide pairs this with GD-05. Timing/path-cache updates not shown.", "url": "https://www.grimdawn.com/wp-content/uploads/sites/3/2019/09/game_bridgeBroken01.jpg"}]}, {"name": "Last Epoch", "edition": "Steam app 899770 \u2022 HUD-hidden caveat", "ids": ["LE-05", "LE-09", "LE-07"], "summary": "Monumental floors, raised platforms, railings and foliage. Gold arcs contrast with green floors; busy clusters hide bodies. Ordinary gameplay camera remains unverified because HUD is absent.", "images": [{"id": "LE-05", "data": "data:image/jpeg;base64,", "observation": "Bridge clearing with four actors, NPC speech icon and foliage/stone edges. No ordinary HUD; composition reference, not default camera evidence.", "url": "https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/899770/ss_3c139fc4555ec7ff180310848c5f59a2b679598f.1920x1080.jpg?t=1781716225"}, {"id": "LE-09", "data": "data:image/jpeg;base64,", "observation": "Gold/red arc at left, green-lit floor at right, diagonal railing crossing foreground, dense combat bodies. Source-rendered combat promotional still; player isolation indeterminate.", "url": "https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/899770/b147fd10d7b8dd0213c4acb99a6bc69be23ef220/ss_b147fd10d7b8dd0213c4acb99a6bc69be23ef220.1920x1080.jpg?t=1781716225"}, {"id": "LE-07", "data": "data:image/jpeg;base64,", "observation": "Opened chest with gold light, monumental circular platform and runic central object. Open state visible; loot event/count and traversability unverified.", "url": "https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/899770/ss_8c8166cac21b3b2b6a46e9a801133f73ba8c85fc.1920x1080.jpg?t=1781716225"}]}];
